export const meta = {
  "slug": "heroicons-exclamation-triangle",
  "family": "heroicons",
  "name": "exclamation-triangle",
  "category": "Interface",
  "motion": "shake",
  "component": "createHeroiconsExclamationTriangleIcon"
};

export function createHeroiconsExclamationTriangleIcon(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderSetIcon(definition, current);
  };
  render();
  const controller = bindSetIcon(root, definition, () => current);
  return {
    play: controller.play,
    reset: controller.reset,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
    get observed() {
      return controller.observed;
    },
  };
}
